# 统计字符串中字符出现的频率
def count_characters(text):
    char_count = {}

    for char in text:
        if char.isalnum():
            char = char.lower()
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

    return char_count

# 测试字符统计
text = "Hello World! How are you?"
frequency = count_characters(text)

print(f"原文本: {text}")
print("
字符出现频率:")
for char, count in sorted(frequency.items()):
    print(f"'{char}': {count}")

# 找出出现最多的字符
most_common = max(frequency.items(), key=lambda x: x[1])
print(f"
出现最多的字符: '{most_common[0]}' ({most_common[1]}次)")
